function labelColor(label:string, colors?:Record<string,string>):string {
  const value=colors?.[label]||state.labelColors[label]||'#8b5cf6';
  if(/[;{}]|url\s*\(|expression\s*\(/i.test(value)) return '#8b5cf6';
  const syntax=/^(?:#[0-9a-f]{3,8}|(?:rgb|hsl)a?\([0-9.,%\s]+\)|(?:color|lab|lch|oklab|oklch|hwb)\([0-9a-z.,%\s/-]+\)|[a-z]{1,24})$/i;
  const supported=typeof CSS!=='undefined'&&typeof CSS.supports==='function'?CSS.supports('color',value):false;
  return syntax.test(value)&&(supported||/^#[0-9a-f]{3,8}$/i.test(value)||/^[a-z]{1,24}$/i.test(value))?value:'#8b5cf6';
}

const app = document.querySelector<HTMLDivElement>('#app') ?? (()=>{const el=document.createElement('div');el.id='app';document.body.append(el);return el;})();
const esc=(s:string)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const message=(e:unknown)=>e instanceof Error?e.message:String(e);
type InvokeFn = <T>(command:string,args?:Record<string,unknown>)=>Promise<T>;
let invokeImpl:InvokeFn|null=null;
export function setInvokeForTests(fn:InvokeFn|null){invokeImpl=fn;}
async function invoke<T>(command:string,args?:Record<string,unknown>):Promise<T>{if(invokeImpl)return invokeImpl<T>(command,args);const api=await import('@tauri-apps/api/core');return api.invoke<T>(command,args);}
type DirectoryPicker=()=>Promise<string|null>;
let directoryPickerForTests:DirectoryPicker|null=null;
export function setDirectoryPickerForTests(fn:DirectoryPicker|null){directoryPickerForTests=fn;}

export async function chooseBoardDirectory():Promise<string|null>{
  if(directoryPickerForTests)return directoryPickerForTests();
  try{const {open}=await import('@tauri-apps/plugin-dialog');const selected=await open({directory:true,multiple:false,title:'Open or create an IrohMD board'});return typeof selected==='string'?selected:null;}
  catch{return null;}
}

export function normalize(x:BackendCard):Card{return {id:x.id,title:x.title,body:x.body,column:x.column||'backlog',labels:x.labels||[],updatedAt:x.updated_at?Date.parse(x.updated_at):Date.now(),revision:x.revision,position:x.position,due:x.due,start:x.start,labelColors:x.label_colors||{}};}
export function renderMarkdown(value:string):string {
  const html=marked.parse(value||'',{async:false}) as string;
  return DOMPurify.sanitize(html,{FORBID_TAGS:['style','script','iframe','object','embed'],ALLOWED_URI_REGEXP:/^(?:(?:https?|mailto):|\/|#)/i});
}
export function sharePath(path:string, root?:string):string {
  const normalized=path.replaceAll('\\','/');
  if(normalized.split('/').includes('..')) throw new Error('Path traversal is not allowed');
  if(root){ const base=root.replaceAll('\\','/').replace(/\/$/,''); const relative=normalized.startsWith(base+'/')?normalized.slice(base.length):normalized; return relative.startsWith('/')?relative:`/${relative}`; }
  return normalized.startsWith('/')?normalized:`/${normalized}`;
}
export function shareCardPath(_boardPath:string, cardId:string):string {
  const safeId=cardId.replaceAll('\\','/').split('/').pop()||'card';
  if(!/^[A-Za-z0-9._~-]+$/.test(safeId)||safeId==='.'||safeId==='..') throw new Error('Invalid card ID');
  return `/cards/${safeId}.md`;
}
function orderedCards(column:Column){return state.cards.filter(card=>card.column===column).sort((a,b)=>(a.position??0)-(b.position??0)||a.updatedAt-b.updatedAt);}
function insertionPosition(column:Column,index:number){const cards=orderedCards(column);const before=cards[index-1]?.position??0;const after=cards[index]?.position??before+2000;return Math.round((before+after)/2)||1000;}
function droppedPosition(id:string,column:Column,target:HTMLElement|null,clientY:number){const cards=orderedCards(column).filter(card=>card.id!==id);if(!target)return insertionPosition(column,cards.length);const targetCard=target.closest<HTMLElement>('.card');if(!targetCard)return insertionPosition(column,cards.length);const targetId=targetCard.dataset.id;let index=cards.findIndex(card=>card.id===targetId);if(index<0)return insertionPosition(column,cards.length);const rect=targetCard.getBoundingClientRect();if(clientY>rect.top+rect.height/2)index++;return insertionPosition(column,index);}
function updateCardDropPreview(id:string,column:Column,target:HTMLElement|null,clientY:number){document.querySelectorAll('.card-drop-placeholder').forEach(node=>node.remove());const dropzone=Array.from(document.querySelectorAll<HTMLElement>('[data-drop-column]')).find(node=>node.dataset.dropColumn===column);if(!dropzone)return;const placeholder=document.createElement('div');placeholder.className='card-drop-placeholder';placeholder.setAttribute('data-card-drop-preview','true');placeholder.setAttribute('aria-hidden','true');const targetCard=target?.closest<HTMLElement>('.card');if(targetCard&&targetCard.dataset.id!==id&&targetCard.parentElement===dropzone){const rect=targetCard.getBoundingClientRect();if(clientY<=rect.top+rect.height/2)dropzone.insertBefore(placeholder,targetCard);else dropzone.insertBefore(placeholder,targetCard.nextSibling);}else dropzone.append(placeholder);}
function updateTab(){if(!state.boardPath)return;const tab={path:state.boardPath,boardId:state.boardId,title:state.boardTitle};const index=state.openBoards.findIndex(x=>x.path===state.boardPath);if(index<0)state.openBoards.push(tab);else state.openBoards[index]=tab;}
export function applyBoardInfo(info:BoardInfo){
  if(!info.board_id)throw new Error('Backend did not return a stable board ID');
  const previousBoardId=state.boardId;state.boardPath=info.path;state.boardId=info.board_id;state.boardTitle=info.title?.trim()||info.path.split(/[\/]/).filter(Boolean).pop()||'My board';state.columns=info.columns?.length?info.columns:defaultColumns();state.labels=info.labels||{};state.labelColors={...state.labels};if(previousBoardId&&previousBoardId!==info.board_id){state.peerId='';state.peerAddress='';state.selected=null;}updateTab();
}
export function setView(view:View){state.view=view;}

export async function loadCards(){if(!state.boardPath)return;state.loading=true;render();try{const result=await invoke<BackendCard[]>('list_cards',{path:state.boardPath});state.cards=(result||[]).map(normalize);state.error='';}catch(e){state.error='Unable to load cards: '+message(e);}finally{state.loading=false;render();}}
export async function parseQuickAdd(text:string):Promise<ParsedCardDraft>{if(!state.boardPath)throw new Error('Open a board before using Quick Add');return invoke<ParsedCardDraft>('parse_quick_add',{path:state.boardPath,text});}

export interface ParsedCardDraft {title:string;body:string;column:string;labels:string[];label_colors?:Record<string,string>;due?:string;start?:string;confidence:number;warnings:string[]}

export async function loadModels(){try{state.modelSettings=await invoke<ModelSettings>('model_settings');state.localModels=await invoke<LocalModel[]>('list_local_models');if(state.modelSettings.provider==='ollama')state.ollamaModels=await invoke<{name:string;size_bytes:number;modified_at?:string}[]>('list_ollama_models',{url:state.modelSettings.ollama_url});else if(state.modelSettings.provider==='openai'){if(state.modelSettings.openai_api_key)await loadOpenAIModels();}else if(state.modelSettings.keep_model_loaded&&state.modelSettings.model_id)await invoke('load_local_model',{id:state.modelSettings.model_id});}catch(e){state.error='Unable to read model settings: '+message(e);render();}}
export async function searchHuggingFace(query:string){if(!query.trim())return;try{state.modelLoading=true;render();state.hfSearchResults=await invoke<HuggingFaceModel[]>("search_huggingface_models",{query:query.trim(),limit:20});state.error="";}catch(e){state.error="Unable to search Hugging Face: "+message(e);}finally{state.modelLoading=false;render();}}
export async function loadOllamaModels(url=state.modelSettings.ollama_url||'http://127.0.0.1:11434'){try{state.modelSettings={...state.modelSettings,ollama_url:url};state.modelLoading=true;render();state.ollamaModels=await invoke<{name:string;size_bytes:number;modified_at?:string}[]>('list_ollama_models',{url});state.error='';}catch(e){state.error='Unable to connect to Ollama: '+message(e);}finally{state.modelLoading=false;render();}}
export async function loadOpenAIModels(baseUrl=state.modelSettings.openai_base_url||'https://openrouter.ai/api/v1',apiKey=state.modelSettings.openai_api_key){try{state.modelSettings={...state.modelSettings,openai_base_url:baseUrl,openai_api_key:apiKey};state.modelLoading=true;render();state.openaiModels=await invoke<OpenAIModel[]>('list_openai_models',{baseUrl,apiKey});state.error='';}catch(e){state.error='Unable to connect to the OpenAI-compatible API: '+message(e);}finally{state.modelLoading=false;render();}}
export async function checkOpenAIAccess(baseUrl=state.modelSettings.openai_base_url||'https://openrouter.ai/api/v1',apiKey=state.modelSettings.openai_api_key){try{state.modelSettings={...state.modelSettings,openai_base_url:baseUrl,openai_api_key:apiKey};state.modelLoading=true;state.modelFeedback='';render();await invoke('check_openai_access',{baseUrl,apiKey});await invoke('save_model_settings',{settings:state.modelSettings});state.error='';state.modelFeedback='Access confirmed. Your API key is valid and saved.';}catch(e){state.modelFeedback='';state.error='Access check failed: '+message(e);}finally{state.modelLoading=false;render();}}
export function applyDownloadProgress(progress:DownloadProgress){state.downloadProgress=progress;if(state.modelLoading)render();}
export async function downloadHFModel(repo_id:string,filename:string){try{state.modelLoading=true;state.downloadProgress={filename,downloaded_bytes:0,total_bytes:null,bytes_per_second:0};state.modelFeedback=`Installing ${filename}…`;state.error='';render();const model=await invoke<LocalModel>('download_huggingface_gguf',{repoId:repo_id,filename});state.localModels=[...state.localModels.filter(item=>item.id!==model.id),model];await saveModelSettings({provider:'huggingface',model_id:model.id});state.modelFeedback=`${model.name} is installed and ready.`;}catch(e){state.error='Unable to install model: '+message(e);state.modelFeedback='';}finally{state.modelLoading=false;state.downloadProgress=null;render();}}

export async function saveModelSettings(settings:ModelSettings){try{const next={...state.modelSettings,...settings};await invoke('save_model_settings',{settings:next});state.modelSettings=next;await loadModels();render();}catch(e){state.error='Unable to save model settings: '+message(e);render();}}
export async function setKeepModelLoaded(keep:boolean){try{state.modelLoading=true;state.modelFeedback=keep?'Loading model…':'Unloading model…';render();const settings={...state.modelSettings,keep_model_loaded:keep};await invoke('save_model_settings',{settings});if(keep&&settings.provider==='huggingface'&&settings.model_id)await invoke('load_local_model',{id:settings.model_id});else if(!keep)await invoke('unload_local_model');state.modelSettings=settings;state.modelFeedback=keep?'Model loaded and ready.':'Model unloaded. It will load only when Quick Add needs it.';}catch(e){state.error='Unable to change model loading: '+message(e);}finally{state.modelLoading=false;render();}}
export async function deleteAllModels(){if(!window.confirm('Delete all locally downloaded models?'))return;try{await invoke('unload_local_model');await invoke('delete_all_local_models');state.localModels=[];if(state.modelSettings.provider==='huggingface'){state.modelSettings={...state.modelSettings,model_id:undefined};await invoke('save_model_settings',{settings:state.modelSettings});}state.modelFeedback='Downloaded models removed.';render();}catch(e){state.error='Unable to delete local models: '+message(e);render();}}

export async function loadSync(){try{const [s,endpoint,peers]=await Promise.all([invoke<{connected:boolean;trusted_peers:number;endpoint_id?:string;address?:string;connection:string}>('sync_status'),invoke<{endpoint_id:string;address:string}>('endpoint_info'),invoke<{peer_id:string;trusted:boolean;address?:string}[]>('list_trusted_peers')]);state.connected=!!s.connected;state.connection=s.connection;state.endpointId=endpoint.endpoint_id||s.endpoint_id||'';state.endpointAddress=endpoint.address||s.address||'';const trusted=peers.filter(x=>x.trusted);state.peer=trusted.map(x=>x.peer_id).join(', ')||'No devices paired';if(!state.peerId&&trusted.length)state.peerId=trusted[0].peer_id;if(!state.peerAddress&&trusted.length)state.peerAddress=trusted.find(x=>x.peer_id===state.peerId)?.address||'';}catch(e){state.error='Unable to read sync status: '+message(e);}render();}
function endpointIdFromAddress(address:string):string{const parsed=JSON.parse(address) as {id?:string};if(!parsed.id||typeof parsed.id!=='string')throw new Error('Endpoint address does not contain an id');return parsed.id;}
export async function pairAddress(address:string){if(!state.boardPath||!state.boardId)throw new Error('Open a board with a stable board ID before pairing');const peerId=endpointIdFromAddress(address);const peer=await invoke<{peer_id:string;trusted:boolean}>('pair_peer_address',{peerId,address,authorizedBoards:[state.boardId]});if(!peer.trusted)throw new Error('Peer was not trusted');state.peerId=peer.peer_id;state.peerAddress=address;await loadSync();return peer;}
export async function syncNow(){if(!state.boardPath||!state.boardId){state.error='Open a board with a stable board ID before syncing.';render();return;}if(!state.peerId||!state.peerAddress){state.error='Pair a peer address before syncing.';render();return;}state.loading=true;render();try{const result=await invoke<{status:string;transferred:number;received:number}>('sync_board',{path:state.boardPath,peerId:state.peerId,address:state.peerAddress});const successfulRoute=['connected','direct','relay'].includes(result.status);state.error=successfulRoute?'':`Sync finished with status: ${result.status}`;await loadCards();await loadSync();if(successfulRoute){state.connected=true;state.connection=result.status;state.error='';render();}}catch(e){state.error='Sync failed: '+message(e);state.loading=false;render();}}

export async function openBoard(){const p=await chooseBoardDirectory();if(!p)return;state.loading=true;state.error='';render();try{const info=await invoke<BoardInfo>('open_or_create_board',{path:p});applyBoardInfo(info);state.view='board';await invoke('watch_board',{path:state.boardPath});await loadCards();await loadSync();}catch(e){state.error='Unable to open board: '+message(e);state.boardPath=null;state.boardId='';state.cards=[];state.loading=false;render();}}
export async function switchBoard(path:string){if(path===state.boardPath){state.view='board';render();return;}state.loading=true;state.error='';render();try{const info=await invoke<BoardInfo>('open_board',{path});applyBoardInfo(info);state.view='board';await invoke('watch_board',{path});await loadCards();}catch(e){state.error='Unable to switch board: '+message(e);state.loading=false;render();}}
function applyMetadata(info:BoardInfo){applyBoardInfo(info);state.error='';render();}
export async function renameBoard(title:string){if(!state.boardPath||!title.trim())return;try{applyMetadata(await invoke<BoardInfo>('rename_board',{path:state.boardPath,title:title.trim()}));}catch(e){state.error='Unable to rename board: '+message(e);render();}}
export async function renameColumn(columnId:string,name:string){if(!state.boardPath||!name.trim())return;try{applyMetadata(await invoke<BoardInfo>('rename_column',{path:state.boardPath,columnId,name:name.trim()}));}catch(e){state.error='Unable to rename column: '+message(e);render();}}
export async function createColumn(name:string){if(!state.boardPath||!name.trim())return;try{applyMetadata(await invoke<BoardInfo>('create_column',{path:state.boardPath,name:name.trim()}));}catch(e){state.error='Unable to create column: '+message(e);render();}}
export async function createLabel(name:string,color:string){if(!state.boardPath||!name.trim())return;try{applyMetadata(await invoke<BoardInfo>('create_label',{path:state.boardPath,name:name.trim(),color}));}catch(e){state.error='Unable to create label: '+message(e);render();}}
export async function updateLabel(name:string,newName:string,color:string){if(!state.boardPath)return;try{applyMetadata(await invoke<BoardInfo>('update_label',{path:state.boardPath,name,newName,color}));}catch(e){state.error='Unable to update label: '+message(e);render();}}
export async function deleteLabel(name:string){if(!state.boardPath)return;try{applyMetadata(await invoke<BoardInfo>('delete_label',{path:state.boardPath,name}));}catch(e){state.error='Unable to delete label: '+message(e);render();}}
export async function reorderColumns(columnIds:string[]){if(!state.boardPath||columnIds.length!==state.columns.length||new Set(columnIds).size!==state.columns.length||columnIds.some(id=>!state.columns.some(column=>column.id===id)))return;const previous=[...state.columns];const byId=new Map(state.columns.map(column=>[column.id,column]));state.columns=columnIds.map(id=>byId.get(id)!);render();try{applyMetadata(await invoke<BoardInfo>('reorder_columns',{path:state.boardPath,columnIds}));}catch(e){state.columns=previous;state.error='Unable to reorder columns: '+message(e);render();}}

async function add(column:Column){if(!state.boardPath){state.error='Open or create a board before adding cards.';render();return;}try{const saved=await invoke<BackendCard>('add_card',{path:state.boardPath,input:{title:'New card',body:'Add a description…',column,labels:[],position:1000}});state.cards.push(normalize(saved));state.selected=saved.id;state.error='';render();}catch(e){state.error='Unable to add card: '+message(e);render();}}
async function save(c:Card){if(!state.boardPath)return;const labels=Array.from(document.querySelector<HTMLSelectElement>('#labels')?.selectedOptions||[],option=>option.value);const input={title:(document.querySelector<HTMLInputElement>('#title')!).value,body:(document.querySelector<HTMLTextAreaElement>('#body')!).value,column:(document.querySelector<HTMLSelectElement>('#column')!).value,labels,label_colors:{...(c.labelColors||{}),...state.labelColors},due:document.querySelector<HTMLInputElement>('#due')?.value||undefined,start:document.querySelector<HTMLInputElement>('#start')?.value||undefined,position:1000};try{const saved=await invoke<BackendCard>('update_card',{path:state.boardPath,id:c.id,input});state.cards=state.cards.map(x=>x.id===c.id?normalize(saved):x);state.selected=null;state.error='';render();}catch(e){state.error='Unable to save card: '+message(e);render();}}
async function remove(id:string){if(!state.boardPath)return;try{await invoke<boolean>('delete_card',{path:state.boardPath,id});state.cards=state.cards.filter(x=>x.id!==id);state.selected=null;state.error='';render();}catch(e){state.error='Unable to delete card: '+message(e);render();}}
function showDialog(dialog:DialogState){state.dialog=dialog;render();queueMicrotask(()=>document.querySelector<HTMLElement>('#dialog-input, #dialog-confirm')?.focus());}
function closeDialog(){state.dialog=null;render();}
function requestDelete(cardId:string){showDialog({kind:'confirm-delete',cardId,title:'Delete card?'});}
function beginInlineEdit(trigger:HTMLElement,value:string,inputId:string,label:string,persist:(next:string)=>Promise<void>){const input=document.createElement('input');input.id=inputId;input.className='inline-title-input';input.value=value;input.setAttribute('aria-label',label);trigger.replaceWith(input);input.focus();input.select();let finished=false;const finish=(save:boolean)=>{if(finished)return;finished=true;const next=input.value.trim();if(save&&next&&next!==value)void persist(next);else render();};input.addEventListener('blur',()=>finish(true));input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();finish(true);}else if(e.key==='Escape'){e.preventDefault();finish(false);}});}
async function submitInputDialog(value:string){const dialog=state.dialog;if(!dialog||dialog.kind!=='input'||!value.trim())return;state.dialog=null;render();switch(dialog.action){case'rename-board':await renameBoard(value);break;case'rename-column':if(dialog.targetId)await renameColumn(dialog.targetId,value);break;case'add-column':await createColumn(value);break;case'pair':try{await pairAddress(value.trim());state.error='';render();}catch(e){state.error='Pairing failed: '+message(e);render();}break;}}
export async function moveCard(id:string,column:Column,position=1000){if(!state.boardPath)return;const old=state.cards.find(x=>x.id===id);if(!old)return;const previous=old.column,previousPosition=old.position;state.cards=state.cards.map(x=>x.id===id?{...x,column,position}:x);render();try{const saved=await invoke<BackendCard>('move_card',{path:state.boardPath,id,column,position});state.cards=state.cards.map(x=>x.id===id?normalize(saved):x);state.error='';render();}catch(e){state.cards=state.cards.map(x=>x.id===id?{...x,column:previous,position:previousPosition}:x);state.error='Unable to move card: '+message(e);render();}}
async function resolveConflict(choice:string){const x=state.conflicts[0];if(!x||!state.boardPath)return;const c=x.localCard||state.cards.find(v=>v.id===x.cardId);if(!c||!x.parentRevisionIds||x.parentRevisionIds.length<2){state.error='Conflict resolution needs two parent revision IDs.';render();return;}const payload={title:c.title,body:c.body,column:c.column,labels:c.labels,position:1000};try{const saved=await invoke<BackendCard>('resolve_conflict',{path:state.boardPath,id:x.cardId,resolution:{choice,local:payload,remote:payload,manual:choice==='manual'?payload:null,parentRevisionIds:x.parentRevisionIds}});state.cards=state.cards.map(v=>v.id===x.cardId?normalize(saved):v);state.conflicts=[];state.error='';render();}catch(e){state.error='Conflict resolution failed: '+message(e);render();}}
export async function poll(){if(!state.boardPath)return;try{const events=await invoke<BackendEvent[]>('poll_watch_events');if(events.length){const bad=events.find(x=>!x.valid&&x.error);if(bad)state.error=bad.error!;const conflict=events.find(x=>x.error?.toLowerCase().includes('conflict'));if(conflict){const id=conflict.path.split('/').pop()?.replace(/\.md$/,'')||'unknown';const local=state.cards.find(c=>c.id===id);state.conflicts=[{cardId:id,local:local?JSON.stringify(local,null,2):'Local version unavailable',remote:conflict.error||'Remote version payload unavailable',base:'Base version unavailable',localCard:local,parentRevisionIds:local?.revision?[local.revision]:[]}];}await loadCards();}}catch(e){state.error='Unable to poll board changes: '+message(e);render();}}

function quickAddShortcut(e:KeyboardEvent){const target=e.target as HTMLElement|null;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='n'&&!target?.closest('input,textarea,select,[contenteditable=\"true\"]')){e.preventDefault();openQuickAdd();}}
document.addEventListener('keydown',quickAddShortcut);

function quickAddModal(){return `<div class="modal-backdrop"><form class="app-dialog quick-add" id="quick-add-form" role="dialog" aria-modal="true"><h2>Quick Add</h2><input id="quick-add-input" autocomplete="off" placeholder="Task due:tomorrow in:doing #label" aria-label="Quick add task"/><p class="notice">Enter creates the card · Shift+Enter creates and opens it · Escape cancels</p><div class="editor-actions"><button type="button" class="secondary" id="quick-add-cancel">Cancel</button><button type="submit" class="primary">Create</button></div></form></div>`;}
function openQuickAdd(){if(!state.boardPath){state.error='Open a board before using Quick Add.';render();return;}if(!state.modelSettings.provider||!state.modelSettings.model_id){state.view='settings';state.error='Choose a local NLP model in Settings before using Quick Add.';render();return;}state.quickAddOpen=true;render();queueMicrotask(()=>document.querySelector<HTMLInputElement>('#quick-add-input')?.focus());}
let quickAddSubmitting=false;
async function submitQuickAdd(text:string,openEditor:boolean){
  if(quickAddSubmitting||!text.trim())return;
  quickAddSubmitting=true;
  const form=document.querySelector<HTMLFormElement>('#quick-add-form');
  form?.setAttribute('aria-busy','true');
  form?.querySelectorAll<HTMLInputElement|HTMLButtonElement>('input,button').forEach(control=>{control.disabled=true;});
  const submit=form?.querySelector<HTMLButtonElement>('button[type=submit]');
  if(submit)submit.textContent='Creating…';
  try{const draft=await parseQuickAdd(text);const saved=await invoke<BackendCard>('add_card',{path:state.boardPath,input:{title:draft.title,body:draft.body,column:draft.column,labels:draft.labels,...(draft.label_colors&&Object.keys(draft.label_colors).length?{label_colors:draft.label_colors}:{}),due:draft.due,start:draft.start,position:1000}});state.cards.push(normalize(saved));state.quickAddOpen=false;state.selected=openEditor?saved.id:null;state.error=draft.warnings.length?draft.warnings.join(' '):'';render();}catch(e){state.error='Quick Add failed: '+message(e);render();}finally{quickAddSubmitting=false;}
}

const editorIcon=(name:'edit'|'close'|'title'|'description'|'column'|'labels'|'calendar'|'flag'|'eye'|'trash'|'archive'|'share'|'check'|'more'|'plus')=>{
  const paths:Record<string,string>={
    edit:'<path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L8 18l-4 1 1-4Z"/>',
    close:'<path d="m18 6-12 12M6 6l12 12"/>',
    title:'<path d="M4 7V4h16v3M9 20h6M12 4v16"/>',
    description:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h6"/>',
    column:'<rect width="18" height="18" x="3" y="3" rx="2"/><path d="M9 3v18M15 3v18"/>',
    labels:'<path d="M20.6 13.1 11 22.7a2.4 2.4 0 0 1-3.4 0l-6.3-6.3a2.4 2.4 0 0 1 0-3.4L10.9 3.4A2 2 0 0 1 12.3 3H19a2 2 0 0 1 2 2v6.7a2 2 0 0 1-.4 1.4Z"/><circle cx="16" cy="8" r="1"/>',
    calendar:'<rect width="18" height="18" x="3" y="4" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>',
    flag:'<path d="M5 22V4M5 4h11l-1 5 1 5H5"/>',
    eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
    trash:'<path d="M3 6h18M8 6V4h8v2M19 6l-1 15H6L5 6M10 11v6M14 11v6"/>',
    archive:'<path d="M4 7h16v13H4zM3 4h18v3H3zM9 11h6"/>',
    share:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 10.5 6.8-4M8.6 13.5l6.8 4"/>',
    check:'<path d="m20 6-11 11-5-5"/>',
    more:'<circle cx="5" cy="12" r="1.4" fill="currentColor" stroke="none"/><circle cx="12" cy="12" r="1.4" fill="currentColor" stroke="none"/><circle cx="19" cy="12" r="1.4" fill="currentColor" stroke="none"/>',
    plus:'<path d="M12 5v14M5 12h14"/>'
  };
  return `<svg class="editor-icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]}</svg>`;
};
function prettyEditorDate(value:string|undefined):string{
  if(!value)return '';
  const d=new Date(value+'T12:00:00');
  return Number.isNaN(d.getTime())?'':new Intl.DateTimeFormat('en',{month:'short',day:'numeric'}).format(d);
}
function editor(c:Card){
  const labels=Array.from(new Set([...Object.keys(state.labels),...c.labels]));
  const startText=prettyEditorDate(c.start),dueText=prettyEditorDate(c.due);
  const dateText=startText&&dueText?`${startText} → ${dueText}`:(startText||dueText||'Dates');
  const chips=c.labels.map(label=>`<button type="button" class="ce-label-chip" data-pop="labelPop" aria-expanded="false"><span class="ce-label-dot" style="background:${esc(labelColor(label,c.labelColors))}"></span><span>${esc(label)}</span></button>`).join('');
  return `<div class="modal-backdrop editor-backdrop"><main class="editor card-editor" role="dialog" aria-modal="true" aria-label="Edit card">
    <header class="ce-header">
      <input id="title" class="ce-title" value="${esc(c.title)}" placeholder="Card title" aria-label="Card title"/>
      <div class="ce-header-actions">
        <button type="button" class="ce-icon-btn" id="share" title="Share" aria-label="Share">${editorIcon('share')}</button>
        <button type="button" class="ce-icon-btn" id="archive" title="Archive card" aria-label="Archive card">${editorIcon('archive')}</button>
        <button type="button" class="ce-icon-btn" id="close" title="Close" aria-label="Close">${editorIcon('close')}</button>
      </div>
    </header>
    <nav class="ce-strip" aria-label="Card properties">
      <span class="ce-label-cluster">${chips}</span>
      <button type="button" class="ce-property" data-pop="datePop" aria-expanded="false">${editorIcon('calendar')}<span id="ce-date-text">${esc(dateText)}</span></button>
      <button type="button" class="ce-property" data-pop="addPop" aria-expanded="false" aria-label="Add property">${editorIcon('plus')}<span>Add</span></button>
      <span class="ce-strip-spacer"></span>
    </nav>
    <section class="ce-md-shell"><div class="ce-md-inner"><textarea id="body" class="ce-md" spellcheck="true" aria-label="Markdown body" placeholder="Start writing…">${esc(c.body)}</textarea></div></section>
    <select id="column" hidden aria-hidden="true" tabindex="-1">${state.columns.map(column=>`<option value="${esc(column.id)}" ${c.column===column.id?'selected':''}>${esc(column.name)}</option>`).join('')}</select>
    <select id="labels" multiple hidden aria-hidden="true" tabindex="-1">${labels.map(label=>`<option value="${esc(label)}" ${c.labels.includes(label)?'selected':''}>${esc(label)}</option>`).join('')}</select>
    <button type="button" id="save" hidden aria-hidden="true">Save</button>
    <button type="button" id="delete" hidden aria-hidden="true">Delete</button>
    <div class="ce-popover" id="labelPop" role="menu"><div class="ce-pop-label">Labels</div>${labels.map(label=>`<div class="ce-menu-row"><button type="button" class="ce-menu-item ${c.labels.includes(label)?'selected':''}" data-toggle-label="${esc(label)}"><span class="ce-swatch" style="background:${esc(labelColor(label,c.labelColors))}"></span>${esc(label)}<span class="ce-check">${editorIcon('check')}</span></button><input type="color" data-card-label-color="${esc(label)}" value="${esc(labelColor(label,c.labelColors))}" aria-label="${esc(label)} color" title="Change ${esc(label)} color"/></div>`).join('')||'<div class="ce-pop-label">No labels yet — add them in Settings</div>'}</div>
    <div class="ce-popover" id="listPop" role="menu"><div class="ce-pop-label">Move to</div>${state.columns.map(column=>`<button type="button" class="ce-menu-item ${c.column===column.id?'selected':''}" data-set-column="${esc(column.id)}">${editorIcon('column')}${esc(column.name)}<span class="ce-check">${editorIcon('check')}</span></button>`).join('')}</div>
    <div class="ce-popover ce-date-pop" id="datePop" role="dialog" aria-label="Edit dates"><div class="ce-pop-label">Dates</div><div class="ce-date-row"><label for="start">Start</label><input id="start" type="date" value="${esc(c.start||'')}"/></div><div class="ce-date-row"><label for="due">Due</label><input id="due" type="date" value="${esc(c.due||'')}"/></div></div>
    <div class="ce-popover" id="addPop" role="menu"><div class="ce-pop-label">Properties</div><button type="button" class="ce-menu-item" data-open-pop="labelPop">${editorIcon('labels')}Labels</button><button type="button" class="ce-menu-item" data-open-pop="listPop">${editorIcon('column')}Move to list</button></div>

  </main></div>`;
}
function closeEditorPopovers(except?:HTMLElement){document.querySelectorAll<HTMLElement>('.ce-popover.open').forEach(pop=>{if(pop!==except)pop.classList.remove('open');});document.querySelectorAll<HTMLElement>('.card-editor [data-pop]').forEach(btn=>{if(!except||btn.dataset.pop!==except.id)btn.setAttribute('aria-expanded','false');});}
function placeEditorPopover(trigger:HTMLElement,pop:HTMLElement){const r=trigger.getBoundingClientRect(),gap=6;pop.style.display='block';const pr=pop.getBoundingClientRect();let left=r.left,top=r.bottom+gap;if(left+pr.width>window.innerWidth-10)left=window.innerWidth-pr.width-10;if(top+pr.height>window.innerHeight-10)top=r.top-pr.height-gap;pop.style.left=Math.max(10,left)+'px';pop.style.top=Math.max(10,top)+'px';pop.style.display='';}
function conflictModal(x:Conflict){const ready=(x.parentRevisionIds?.length||0)>=2;return `<div class="modal-backdrop"><section class="conflict" role="dialog" aria-modal="true"><div class="editor-head"><span>CONFLICT DETECTED</span></div><h2>Conflict requires review</h2><p>${esc(x.remote)}</p>${!ready?'<p class="error">Resolution awaits two parent revision IDs from the backend.</p>':''}<div class="editor-actions"><button data-resolve="local" ${ready?'':'disabled'}>Keep local</button><button data-resolve="remote" ${ready?'':'disabled'}>Keep remote</button><button data-resolve="manual" ${ready?'':'disabled'}>Manual merge</button></div></section></div>`;}
function settingsToggle(){const settings=state.view==='settings';return `<button class="settings-toggle ${settings?'active':''}" data-view="${settings?'board':'settings'}" aria-label="${settings?'Return to board':'Open settings'}" title="${settings?'Return to board':'Settings'}">${settings?'←':'⚙'}</button>`;}
function boardPage(){if(!state.boardPath)return '<section class="workspace empty"><div><h1>Open a board to get started</h1><p>Choose a folder to open or create a board.</p><button class="primary" id="empty-open">Open board</button></div></section>';return `<section class="workspace" data-page="board"><div class="toolbar"><div class="board-title-menu"><div class="title-row"><h1><button class="editable-heading" id="rename-board" aria-label="Rename board" title="Click to rename">${esc(state.boardTitle)}</button></h1></div><div class="board-switcher" role="menu" aria-label="Open boards">${state.openBoards.filter(board=>board.path!==state.boardPath).map(board=>`<button role="menuitem" data-board-path="${esc(board.path)}" class="board-menu-item ${board.path===state.boardPath?'active':''}">${esc(board.title)}</button>`).join('')}<button role="menuitem" class="board-menu-item board-menu-open" id="open" aria-label="Open or create board">＋</button></div></div><div class="toolbar-actions"><span class="status board-sync-status ${state.connected?'online':'offline'}" role="status"><i></i>${state.connected?'Synced':'Offline'}</span><div class="create-actions" role="group" aria-label="Create"><button class="create-action card-action reveal-action" id="new-card" aria-label="Add card" title="Add card"><span class="action-label">Add card</span><span class="plus-icon">＋</span></button><button class="create-action column-action reveal-action" id="add-column" aria-label="Add column" title="Add column"><span class="action-label">Add column</span><span class="plus-icon">＋</span></button></div></div></div>${state.loading?'<p class="notice">Loading…</p>':''}${state.error?`<p class="error" role="alert">${esc(state.error)}</p>`:''}<div class="columns">${state.columns.map(column=>`<section class="column" data-column="${esc(column.id)}"><div class="column-head"><div><div class="column-title"><h2><button class="editable-column-heading" data-rename-column="${esc(column.id)}" aria-label="Rename ${esc(column.name)}" title="Click to rename">${esc(column.name)}</button> <b>${state.cards.filter(x=>x.column===column.id).length}</b></h2></div></div><button class="add reveal-action" data-add="${esc(column.id)}" aria-label="Add card to ${esc(column.name)}"><span class="action-label">Add card</span><span class="plus-icon">＋</span></button></div><div class="dropzone" data-drop-column="${esc(column.id)}" role="group" aria-label="${esc(column.name)} cards">${orderedCards(column.id).map(c=>`<article class="card ${state.selected===c.id?'selected':''}" tabindex="0" aria-label="${esc(c.title)}. Hold Alt and press left or right arrow to move." data-id="${esc(c.id)}"><h3>${esc(c.title)}</h3><div class="card-body">${renderMarkdown(c.body)}</div><div class="card-foot">${c.due?`<time class="due-date" datetime="${esc(c.due)}" aria-label="Due ${esc(c.due)}"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></svg>${esc(prettyEditorDate(c.due)||c.due)}</time>`:''}${c.labels.map(l=>`<span class="tag" style="--label-color:${esc(labelColor(l,c.labelColors))}">${esc(l)}</span>`).join('')}</div></article>`).join('')}</div></section>`).join('')}</div></section>`;}
function appDialog(dialog:DialogState){if(dialog.kind==='confirm-delete')return `<div class="modal-backdrop"><section class="app-dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">Delete card?</h2><p>This action cannot be undone.</p><div class="editor-actions"><button class="secondary" id="dialog-cancel">Cancel</button><button class="primary danger-action" id="dialog-confirm">Delete card</button></div></section></div>`;const field=dialog.multiline?`<textarea id="dialog-input" aria-label="${esc(dialog.label)}">${esc(dialog.value)}</textarea>`:`<input id="dialog-input" aria-label="${esc(dialog.label)}" value="${esc(dialog.value)}"/>`;return `<div class="modal-backdrop"><form class="app-dialog" id="input-dialog-form" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${esc(dialog.title)}</h2><label>${esc(dialog.label)}${field}</label><div class="editor-actions"><button type="button" class="secondary" id="dialog-cancel">Cancel</button><button type="submit" class="primary">${dialog.action==='pair'?'Pair device':'Save'}</button></div></form></div>`;}
function legacySettingsPage(){return `<section class="workspace settings" data-page="settings"><div class="settings-header"><h1>Sync settings</h1><p>Manage device pairing, endpoint details, and manual synchronization.</p></div>${state.error?`<p class="error" role="alert">${esc(state.error)}</p>`:''}<div class="settings-grid"><section class="settings-card"><h2>Local NLP model</h2><p>Quick Add uses a local model only for parsing input.</p><h3>Recommended for this Mac</h3><ul class="model-recommendations">${recommendedModels.map(m=>`<li><strong>${esc(m.note)}</strong><br><code>${esc(m.repo)}</code><br><small>${esc(m.file)} · ${esc(m.size)}</small></li>`).join('')}</ul><h3>Search Hugging Face</h3><div class="hf-search"><input id="hf-search" placeholder="Search models, e.g. Qwen GGUF"/><button type="button" class="secondary" id="search-hf">Search</button></div><ul class="model-recommendations">${state.hfSearchResults.map(m=>`<li><a href="https://huggingface.co/${encodeURI(m.id)}" target="_blank" rel="noreferrer">${esc(m.id)}</a><br><small>${m.downloads.toLocaleString()} downloads · ${m.likes.toLocaleString()} likes</small> <button type="button" class="secondary" data-use-hf="${esc(m.id)}">Use repository</button></li>`).join('')}</ul><label>Provider<select id="model-provider"><option value="huggingface">Hugging Face GGUF</option><option value="ollama">Ollama</option></select></label><label>Ollama URL<input id="ollama-url" value="http://127.0.0.1:11434"/></label><label>Ollama model<input id="ollama-model" placeholder="e.g. qwen2.5:1.5b"/></label><label>HF repository<input id="hf-repo" placeholder="owner/model"/></label><label>HF GGUF filename<input id="hf-file" placeholder="model.Q4_K_M.gguf"/></label><button type="button" class="secondary" id="download-hf-model">Download HF model</button><div class="editor-actions"><button class="primary" id="save-model-settings">Save model settings</button><button class="danger" id="delete-all-models">Delete all local models</button></div></section><section class="settings-card"><h2>Connection</h2><div class="setting-status"><span class="status ${state.connected?'online':'offline'}"><i></i>${state.connected?'Connected':'Offline'}</span><strong>${esc(state.connection)}</strong></div><p>${state.connected?'Connected to '+esc(state.peer):esc(state.peer)}</p><button class="primary" id="sync" ${!state.boardPath||state.loading?'disabled':''}>↻ Sync current board</button></section><section class="settings-card"><h2>Pair a device</h2><p>Pair using the full serialized endpoint address from another device.</p><button class="secondary" id="pair" ${!state.boardPath?'disabled':''}>⌘ Pair device</button></section><section class="settings-card endpoint-card"><h2>Local endpoint</h2><code title="${esc(state.endpointAddress)}">${state.endpointAddress?esc(state.endpointAddress):'Starting…'}</code><div class="endpoint-id">ID: ${esc(state.endpointId||'Not ready')}</div><button class="secondary" id="copy-endpoint">Copy endpoint</button></section><section class="settings-card"><h2>Current board</h2><p>${state.boardPath?esc(state.boardTitle):'No board open'}</p><code>${state.boardPath?esc(state.boardId):'Open a board to configure sync'}</code></section></div></section>`;}

function formatBytes(bytes:number){if(!bytes)return 'Size unknown';const units=['B','KB','MB','GB'];const index=Math.min(Math.floor(Math.log(bytes)/Math.log(1024)),units.length-1);return `${(bytes/1024**index).toFixed(index>1?1:0)} ${units[index]}`;}
function modelName(id:string){return state.localModels.find(model=>model.id===id)?.name||state.ollamaModels.find(model=>model.name===id)?.name||state.openaiModels.find(model=>model.id===id)?.id||id;}
function modelSettingsSection(){
  const usingOllama=state.modelSettings.provider==='ollama';
  const usingOpenAI=state.modelSettings.provider==='openai';
  const active=state.modelSettings.model_id;
  const installed=state.localModels.map(model=>`<button type="button" class="model-row ${active===model.id?'selected':''}" data-select-model="${esc(model.id)}"><span class="model-icon">${active===model.id?'✓':'◇'}</span><span><strong>${esc(model.name)}</strong><small>${formatBytes(model.size_bytes)} · On this Mac</small></span><b>${active===model.id?'Active':'Use'}</b></button>`).join('');
  const recommended=recommendedModels.slice(0,4).map((model,index)=>`<article class="model-card ${index===0?'featured':''}"><div><span class="model-kicker">${index===0?'Recommended':esc(model.size)}</span><h3>${esc(model.note)}</h3><p>${esc(model.repo.split('/').pop()?.replace(/-GGUF$/i,'')||model.repo)}</p></div><button type="button" class="${index===0?'primary':'secondary'}" data-install-recommended data-repo="${esc(model.repo)}" data-file="${esc(model.file)}" ${state.modelLoading?'disabled':''}>${state.modelLoading?'Please wait…':'Install'}</button></article>`).join('');
  const ollama=state.ollamaModels.length?state.ollamaModels.map(model=>`<button type="button" class="model-row ${active===model.name?'selected':''}" data-select-ollama="${esc(model.name)}"><span class="model-icon">${active===model.name?'✓':'◇'}</span><span><strong>${esc(model.name)}</strong><small>${formatBytes(model.size_bytes)} · Ollama</small></span><b>${active===model.name?'Active':'Use'}</b></button>`).join(''):'<div class="empty-models"><strong>No Ollama models found</strong><span>Start Ollama or install a model, then refresh above.</span></div>';
  const openai=state.modelSettings.openai_api_key?state.openaiModels.length?state.openaiModels.map(model=>`<button type="button" class="model-row ${active===model.id?'selected':''}" data-select-openai="${esc(model.id)}"><span class="model-icon">${active===model.id?'✓':'◇'}</span><span><strong>${esc(model.id)}</strong><small>OpenAI-compatible API${model.owned_by?' · '+esc(model.owned_by):''}</small></span><b>${active===model.id?'Active':'Use'}</b></button>`).join(''):'<div class="empty-models"><strong>No models found</strong><span>Check the endpoint, API key, or enter a model ID below.</span></div>':'<div class="empty-models"><strong>API key required</strong><span>Add your API key and connect to list models.</span></div>';
  const openaiPanel=`<div class="model-panel"><div class="panel-title"><h3>OpenAI-compatible API</h3><button type="button" class="text-button" id="refresh-openai">Connect</button><button type="button" class="text-button" id="check-openai-access">Check access</button></div>${state.modelFeedback?`<p class="model-feedback" role="status">${esc(state.modelFeedback)}</p>`:''}<label>Base URL<input id="openai-base-url" value="${esc(state.modelSettings.openai_base_url||'https://openrouter.ai/api/v1')}"/></label><label>API key<input id="openai-api-key" type="password" value="${esc(state.modelSettings.openai_api_key||'')}"/></label><div class="installed-models">${openai}</div><div class="custom-install"><label>Model ID<input id="openai-model" placeholder="e.g. anthropic/claude-sonnet-4"/></label><button type="button" class="secondary" id="use-openai-model">Use model</button></div></div>`;
  return `<section class="settings-section model-settings" data-settings-section="models"><div class="section-heading"><div><span class="eyebrow">QUICK ADD</span><h2>AI model</h2><p>Choose what powers natural-language card creation.</p></div><div class="model-setup-status ${active?'ready':''}"><i></i><span><strong>${active?'Ready':'Choose a model'}</strong><small>${active?esc(modelName(active)):'Install a recommended option below'}</small></span></div></div><div class="provider-switch" role="tablist" aria-label="Model source"><button type="button" role="tab" data-model-provider="huggingface" aria-selected="${!usingOllama&&!usingOpenAI}">On this Mac</button><button type="button" role="tab" data-model-provider="ollama" aria-selected="${usingOllama}">Ollama</button><button type="button" role="tab" data-model-provider="openai" aria-selected="${usingOpenAI}">OpenAI API</button></div>${usingOpenAI?'':`<label class="model-retention"><input type="checkbox" id="keep-model-loaded" ${state.modelSettings.keep_model_loaded?'checked':''} ${!active||state.modelLoading?'disabled':''}/><span><strong>Keep model loaded</strong><small>${state.modelSettings.keep_model_loaded?'Loaded for faster Quick Add':'Unload after each Quick Add to save memory'}</small></span></label>`}${usingOllama?`<div class="model-panel"><div class="panel-title"><h3>Available in Ollama</h3><button type="button" class="text-button" id="refresh-ollama">Refresh</button></div><div class="installed-models">${ollama}</div><details class="advanced-settings"><summary>Connection</summary><label>Ollama URL<input id="ollama-url" value="${esc(state.modelSettings.ollama_url||'http://127.0.0.1:11434')}"/></label></details></div>`:usingOpenAI?openaiPanel:`<div class="model-panel">${state.modelFeedback?`<p class="model-feedback" role="status">${esc(state.modelFeedback)}</p>`:''}${state.modelLoading&&state.downloadProgress?`<div class="download-progress" role="status" aria-live="polite"><div><strong>Downloading ${esc(state.downloadProgress.filename)}</strong><span>${formatBytes(state.downloadProgress.downloaded_bytes)}${state.downloadProgress.total_bytes?' of '+formatBytes(state.downloadProgress.total_bytes):''}</span></div><progress max="100" ${state.downloadProgress.total_bytes?`value="${Math.min(100,state.downloadProgress.downloaded_bytes/state.downloadProgress.total_bytes*100)}"`:''}>${state.downloadProgress.total_bytes?Math.round(state.downloadProgress.downloaded_bytes/state.downloadProgress.total_bytes*100):0}%</progress><div class="download-meta"><span>${state.downloadProgress.total_bytes?Math.round(state.downloadProgress.downloaded_bytes/state.downloadProgress.total_bytes*100)+'%':'Preparing…'}</span><b>${state.downloadProgress.bytes_per_second?formatBytes(state.downloadProgress.bytes_per_second)+'/s':'Connecting…'}</b></div></div>`:''}${installed?`<div class="panel-title"><h3>Installed</h3><span>${state.localModels.length} ${state.localModels.length===1?'model':'models'}</span></div><div class="installed-models">${installed}</div>`:''}<div class="panel-title discover-title"><div><h3>Recommended</h3><span>One click installs and activates</span></div></div><div class="model-gallery">${recommended}</div><details class="advanced-settings" ${state.hfSearchResults.length?'open':''}><summary>Find another Hugging Face model</summary><form class="hf-search" id="hf-search-form"><input id="hf-search" placeholder="Search GGUF models" aria-label="Search Hugging Face models"/><button type="submit" class="secondary">Search</button></form>${state.hfSearchResults.length?`<div class="search-results">${state.hfSearchResults.map(model=>`<div class="search-result"><a href="https://huggingface.co/${encodeURI(model.id)}" target="_blank" rel="noreferrer"><strong>${esc(model.id)}</strong><small>${model.downloads.toLocaleString()} downloads</small></a><button type="button" class="text-button" data-use-hf="${esc(model.id)}">Choose</button></div>`).join('')}</div>`:''}<div class="custom-install"><label>Repository<input id="hf-repo" placeholder="owner/model"/></label><label>Exact .gguf file<input id="hf-file" placeholder="model.Q4_K_M.gguf"/></label><button type="button" class="secondary" id="download-hf-model">Install and use</button></div></details>${state.localModels.length?`<details class="danger-zone"><summary>Manage storage</summary><button class="danger" id="delete-all-models">Delete all downloaded models</button></details>`:''}</div>`}</section>`;
}
function labelsSettingsSection(){
  const rows=Object.entries(state.labels).map(([name,color])=>`<div class="label-row" data-label-row="${esc(name)}"><input data-label-name value="${esc(name)}" aria-label="Label name"/><input type="color" data-label-color value="${esc(labelColor(name,{[name]:color}))}" aria-label="Label color"/><button type="button" class="secondary" data-update-label>Save</button><button type="button" class="danger" data-delete-label>Delete</button></div>`).join('');
  return `<section class="settings-section labels-settings" data-settings-section="labels"><div class="section-heading"><div><span class="eyebrow">BOARD</span><h2>Labels</h2><p>Create labels and keep their colors consistent across cards.</p></div></div><form id="create-label-form" class="label-create"><label>Name<input id="new-label-name" required maxlength="80" aria-label="New label name"/></label><label>Color<input id="new-label-color" type="color" value="#8b5cf6" aria-label="New label color"/></label><button class="primary" type="submit">Add label</button></form><div class="label-list">${rows||'<p class="notice">No labels yet.</p>'}</div></section>`;
}
function syncSettingsSection(){return `<section class="settings-section sync-settings" data-settings-section="sync"><div class="section-heading"><div><span class="eyebrow">IROH</span><h2>Sync</h2><p>Keep this board in step with your other devices.</p></div><span class="status ${state.connected?'online':'offline'}"><i></i>${state.connected?'Connected':'Offline'}</span></div><div class="sync-actions"><div><strong>${state.boardPath?esc(state.boardTitle):'No board open'}</strong><span>${state.connected?'Connected to '+esc(state.peer):esc(state.peer)}</span></div><button class="secondary" id="pair" ${!state.boardPath?'disabled':''}>Pair device</button><button class="primary" id="sync" ${!state.boardPath||state.loading?'disabled':''}>${state.loading?'Syncing…':'Sync now'}</button></div><details class="advanced-settings device-details"><summary>Device details</summary><div class="device-grid"><div><span>Local endpoint</span><code title="${esc(state.endpointAddress)}">${state.endpointAddress?esc(state.endpointAddress):'Starting…'}</code><button class="text-button" id="copy-endpoint">Copy address</button></div><div><span>Board ID</span><code>${state.boardPath?esc(state.boardId):'Open a board to enable sync'}</code></div></div></details></section>`;}
function settingsPage(){return `<section class="workspace settings" data-page="settings"><div class="settings-header"><span class="eyebrow">IROHMD</span><h1>Settings</h1><p>Models and sync, without the setup maze.</p></div>${state.error?`<p class="error" role="alert">${esc(state.error)}</p>`:''}<div class="settings-layout">${modelSettingsSection()}${labelsSettingsSection()}${syncSettingsSection()}</div></section>`;}


