  const mdBody=document.querySelector<HTMLTextAreaElement>('#body.ce-md');const autosizeBody=()=>{if(!mdBody)return;mdBody.style.height='auto';mdBody.style.height=Math.max(320,mdBody.scrollHeight)+'px';};autosizeBody();mdBody?.addEventListener('input',autosizeBody);
